o'=>$documento,'folios'=>$folios===''?null:(int)$folios]);echo json_encode(['ok'=>true,'id'=>(int)$db->lastInsertId(),'mensaje'=>'Solicitud de anulación registrada correctamente.'],JSON_UNESCAPED_UNICODE);
